const bundle = msg.payload || {};
const weatherResponse = bundle.weather || {};
const alertsResponse = bundle.alerts || {};
const w = weatherResponse.weather;

if (!w || typeof w !== "object") {
    node.error("No weather object was returned by the DWD data service", msg);
    return [null, null];
}

const numberOr = (value, fallback = 0) => {
    const n = Number(value);
    return Number.isFinite(n) ? n : fallback;
};

const now = new Date();
const forecastFor = new Date(now.getTime() + 10 * 60 * 1000);
const previous = flow.get("stadePreviousWeather") || null;
const allAlerts = Array.isArray(alertsResponse.alerts) ? alertsResponse.alerts : [];
const activeAlerts = allAlerts.filter((a) => {
    const onset = a.onset ? new Date(a.onset) : now;
    const expires = a.expires ? new Date(a.expires) : forecastFor;
    return onset <= forecastFor && expires > now && a.status !== "cancelled";
});

const gust = numberOr(w.wind_gust_speed_10, numberOr(w.wind_gust_speed_30));
const wind = numberOr(w.wind_speed_10, numberOr(w.wind_speed_30));
const rain10 = numberOr(w.precipitation_10);
const visibility = numberOr(w.visibility, 50000);
const pressure = numberOr(w.pressure_msl, 1013);
const temperature = numberOr(w.temperature);
const condition = String(w.condition || "unknown").toLowerCase();

let score = 0;
const reasons = [];

const severityPoints = {
    minor: 15,
    moderate: 35,
    severe: 60,
    extreme: 85
};
let strongestAlert = null;
for (const alert of activeAlerts) {
    const severity = String(alert.severity || "minor").toLowerCase();
    const points = severityPoints[severity] || 15;
    if (!strongestAlert || points > strongestAlert.points) {
        strongestAlert = { points, alert };
    }
}
if (strongestAlert) {
    score += strongestAlert.points;
    reasons.push(`Active DWD ${strongestAlert.alert.severity || "weather"} alert: ${strongestAlert.alert.event_en || strongestAlert.alert.event_de || "weather warning"}`);
}

if (gust >= 90) {
    score += 50;
    reasons.push(`Very dangerous gusts: ${gust.toFixed(1)} km/h`);
} else if (gust >= 70) {
    score += 38;
    reasons.push(`Strong storm gusts: ${gust.toFixed(1)} km/h`);
} else if (gust >= 55) {
    score += 25;
    reasons.push(`Severe gust threshold approached: ${gust.toFixed(1)} km/h`);
} else if (gust >= 40) {
    score += 10;
    reasons.push(`Elevated gusts: ${gust.toFixed(1)} km/h`);
}

if (wind >= 60) {
    score += 25;
    reasons.push(`Very strong sustained wind: ${wind.toFixed(1)} km/h`);
} else if (wind >= 40) {
    score += 15;
    reasons.push(`Strong sustained wind: ${wind.toFixed(1)} km/h`);
} else if (wind >= 25) {
    score += 5;
    reasons.push(`Breezy conditions: ${wind.toFixed(1)} km/h`);
}

if (rain10 >= 10) {
    score += 40;
    reasons.push(`Very heavy 10-minute rain: ${rain10.toFixed(1)} mm`);
} else if (rain10 >= 5) {
    score += 28;
    reasons.push(`Heavy 10-minute rain: ${rain10.toFixed(1)} mm`);
} else if (rain10 >= 2) {
    score += 18;
    reasons.push(`Intense 10-minute rain: ${rain10.toFixed(1)} mm`);
} else if (rain10 >= 0.5) {
    score += 6;
    reasons.push(`Rain detected: ${rain10.toFixed(1)} mm/10 min`);
}

if (visibility < 1000) {
    score += 25;
    reasons.push(`Very low visibility: ${Math.round(visibility)} m`);
} else if (visibility < 5000) {
    score += 12;
    reasons.push(`Reduced visibility: ${Math.round(visibility)} m`);
}

if (/thunder|storm|hail|freezing|ice/.test(condition)) {
    score += 30;
    reasons.push(`Potentially hazardous condition: ${condition}`);
}
if (temperature >= 35 || temperature <= -10) {
    score += 15;
    reasons.push(`Extreme temperature signal: ${temperature.toFixed(1)} °C`);
}

let trend = {
    available: false,
    minutes_between_samples: null,
    pressure_change_hpa: null,
    gust_change_kmh: null,
    rain_change_mm_10min: null
};

if (previous && previous.observed_at) {
    const elapsedMinutes = (now.getTime() - new Date(previous.observed_at).getTime()) / 60000;
    const pressureChange = pressure - numberOr(previous.pressure_msl, pressure);
    const gustChange = gust - numberOr(previous.gust_kmh, gust);
    const rainChange = rain10 - numberOr(previous.rain_10min_mm, rain10);
    trend = {
        available: true,
        minutes_between_samples: Math.round(elapsedMinutes * 10) / 10,
        pressure_change_hpa: Math.round(pressureChange * 10) / 10,
        gust_change_kmh: Math.round(gustChange * 10) / 10,
        rain_change_mm_10min: Math.round(rainChange * 10) / 10
    };

    if (pressureChange <= -3) {
        score += 20;
        reasons.push(`Rapid pressure fall: ${pressureChange.toFixed(1)} hPa`);
    } else if (pressureChange <= -1.5) {
        score += 10;
        reasons.push(`Falling pressure: ${pressureChange.toFixed(1)} hPa`);
    }
    if (gustChange >= 20) {
        score += 18;
        reasons.push(`Gusts rising rapidly: +${gustChange.toFixed(1)} km/h`);
    } else if (gustChange >= 10) {
        score += 9;
        reasons.push(`Gusts increasing: +${gustChange.toFixed(1)} km/h`);
    }
    if (rainChange >= 3) {
        score += 12;
        reasons.push(`Rain intensity rising: +${rainChange.toFixed(1)} mm/10 min`);
    }
}

score = Math.max(0, Math.min(100, Math.round(score)));
const severe = score >= 50 || Boolean(strongestAlert && strongestAlert.points >= 60);
let riskLevel = "LOW";
if (score >= 75) riskLevel = "EXTREME";
else if (score >= 50) riskLevel = "SEVERE";
else if (score >= 25) riskLevel = "ELEVATED";

if (reasons.length === 0) reasons.push("No severe-weather indicators detected in the latest DWD data");

const source = Array.isArray(weatherResponse.sources) && weatherResponse.sources.length
    ? weatherResponse.sources[0]
    : {};

const result = {
    location: alertsResponse.location?.name || "Stade",
    generated_at: now.toISOString(),
    prediction_for: forecastFor.toISOString(),
    prediction_horizon_minutes: 10,
    severe_weather_predicted: severe,
    risk_level: riskLevel,
    risk_score: score,
    confidence_percent: activeAlerts.length ? 90 : (trend.available ? 75 : 60),
    reasons,
    official_dwd_alerts: activeAlerts.map((a) => ({
        severity: a.severity,
        event: a.event_en || a.event_de,
        headline: a.headline_en || a.headline_de,
        onset: a.onset,
        expires: a.expires,
        instruction: a.instruction_en || a.instruction_de
    })),
    current_weather: {
        observed_at: w.timestamp,
        station: source.station_name || "Nearest DWD station",
        dwd_station_id: source.dwd_station_id || null,
        condition: w.condition || null,
        temperature_c: temperature,
        relative_humidity_percent: numberOr(w.relative_humidity),
        pressure_msl_hpa: pressure,
        precipitation_10min_mm: rain10,
        wind_speed_10min_kmh: wind,
        wind_gust_10min_kmh: gust,
        visibility_m: visibility,
        solar_irradiation_10min_kwh_m2: w.solar_10 === null || w.solar_10 === undefined
            ? null
            : numberOr(w.solar_10, null)
    },
    ten_minute_trend: trend,
    model: "local_explainable_severe_weather_model_v1",
    disclaimer: "Experimental 10-minute risk prediction; official DWD warnings remain authoritative."
};

flow.set("stadePreviousWeather", {
    observed_at: now.toISOString(),
    pressure_msl: pressure,
    gust_kmh: gust,
    rain_10min_mm: rain10
});
flow.set("stadeLatestPrediction", result);

node.status({
    fill: severe ? "red" : (riskLevel === "ELEVATED" ? "yellow" : "green"),
    shape: severe ? "dot" : "ring",
    text: `${riskLevel} ${score}/100 • next 10 min`
});

msg.topic = "stade/weather/severity_prediction";
msg.payload = result;

const severeAlertMessage = severe ? {
    topic: "stade/weather/severe_alert",
    payload: result
} : null;

return [msg, severeAlertMessage];

const latest = flow.get("stadeLatestPrediction");
msg.headers = { "content-type": "application/json; charset=utf-8" };
if (!latest) {
    msg.statusCode = 503;
    msg.payload = {
        error: "No prediction is available yet",
        instruction: "Wait for the first DWD weather check or click the inject node."
    };
    return msg;
}
msg.statusCode = 200;
msg.payload = latest;
return msg;

const stored = flow.get("stadeMqttSensors") || {};
const sensors = {
    temperature: stored.temperature || { value: null, updated_at: null, topic: "room/temperature", sensor: "DHT11" },
    humidity: stored.humidity || { value: null, updated_at: null, topic: "room/humidity", sensor: "DHT11" },
    light_intensity: stored.light_intensity || { value: null, updated_at: null, topic: "room/LightIntensity", sensor: "LDR" }
};

let prediction = flow.get("stadeLatestPrediction") || null;

const readNumber = (payload, keys) => {
    if (typeof payload === "number") return Number.isFinite(payload) ? payload : null;
    if (typeof payload === "string") {
        const direct = Number.parseFloat(payload);
        if (Number.isFinite(direct)) return direct;
        try {
            return readNumber(JSON.parse(payload), keys);
        } catch (_) {
            return null;
        }
    }
    if (payload && typeof payload === "object") {
        for (const key of keys) {
            const value = Number(payload[key]);
            if (Number.isFinite(value)) return value;
        }
    }
    return null;
};

const round1 = (value) => Math.round(value * 10) / 10;
const clampPercent = (value) => Math.max(0, Math.min(100, value));
const now = new Date().toISOString();
const topic = String(msg.topic || "");

if (topic === "stade/weather/severity_prediction" || msg.payload?.current_weather) {
    prediction = msg.payload;
    flow.set("stadeLatestPrediction", prediction);
} else if (topic === "room/temperature") {
    const value = readNumber(msg.payload, ["temperature", "Temperature", "temp", "value"]);
    if (value !== null) sensors.temperature = { value, updated_at: now, topic, sensor: "DHT11" };
} else if (topic === "room/humidity") {
    const value = readNumber(msg.payload, ["humidity", "Humidity", "relative_humidity", "value"]);
    if (value !== null) sensors.humidity = { value, updated_at: now, topic, sensor: "DHT11" };
} else if (topic === "room/LightIntensity") {
    const value = readNumber(msg.payload, ["LightIntensity", "lightIntensity", "light_intensity", "ldr", "LDR", "value"]);
    if (value !== null) {
        sensors.light_intensity = {
            value: round1(clampPercent(value)),
            updated_at: now,
            topic,
            sensor: "LDR"
        };
    }
}

flow.set("stadeMqttSensors", sensors);

const base = prediction && typeof prediction === "object" ? prediction : {};
const weather = base.current_weather || {};
const dwdTemperature = Number(weather.temperature_c);
const dwdHumidity = Number(weather.relative_humidity_percent);
const dwdSolar10 = Number(weather.solar_irradiation_10min_kwh_m2);
const dwdSolarWm2 = Number.isFinite(dwdSolar10) ? dwdSolar10 * 6000 : null;
const dwdLightPercent = Number.isFinite(dwdSolarWm2) ? clampPercent(dwdSolarWm2 / 10) : null;
const sensorTemperature = Number(sensors.temperature.value);
const sensorHumidity = Number(sensors.humidity.value);
const sensorLight = Number(sensors.light_intensity.value);

msg.topic = "stade/weather/dashboard";
msg.payload = {
    ...base,
    mqtt_sensors: sensors,
    sensor_comparison: {
        formula: "Real sensor minus DWD observation",
        temperature: {
            sensor: "DHT11",
            sensor_c: Number.isFinite(sensorTemperature) ? sensorTemperature : null,
            dwd_c: Number.isFinite(dwdTemperature) ? dwdTemperature : null,
            difference_c: Number.isFinite(sensorTemperature) && Number.isFinite(dwdTemperature)
                ? round1(sensorTemperature - dwdTemperature)
                : null
        },
        humidity: {
            sensor: "DHT11",
            sensor_percent: Number.isFinite(sensorHumidity) ? sensorHumidity : null,
            dwd_percent: Number.isFinite(dwdHumidity) ? dwdHumidity : null,
            difference_percent: Number.isFinite(sensorHumidity) && Number.isFinite(dwdHumidity)
                ? round1(sensorHumidity - dwdHumidity)
                : null
        },
        light_intensity: {
            sensor: "LDR",
            sensor_percent: Number.isFinite(sensorLight) ? sensorLight : null,
            dwd_solar_10_kwh_m2: Number.isFinite(dwdSolar10) ? dwdSolar10 : null,
            dwd_average_wm2: Number.isFinite(dwdSolarWm2) ? round1(dwdSolarWm2) : null,
            dwd_normalized_percent: Number.isFinite(dwdLightPercent) ? round1(dwdLightPercent) : null,
            difference_percent: Number.isFinite(sensorLight) && Number.isFinite(dwdLightPercent)
                ? round1(sensorLight - dwdLightPercent)
                : null
        }
    }
};

const temperatureLive = Number.isFinite(sensorTemperature);
const humidityLive = Number.isFinite(sensorHumidity);
const lightLive = Number.isFinite(sensorLight);
const liveCount = Number(temperatureLive) + Number(humidityLive) + Number(lightLive);

node.status({
    fill: liveCount === 3 ? "green" : "yellow",
    shape: "dot",
    text: `${liveCount}/3 sensors live`
});

return msg;

const previous = flow.get("actuatorsAndSensorsState") || {};
const state = {
    startRobot: previous.startRobot ?? null,
    stopRobot: previous.stopRobot ?? null,
    startButton: previous.startButton ?? null,
    stopButton: previous.stopButton ?? null,
    robot: previous.robot ?? null,
    conveyor: previous.conveyor ?? null,
    temperature: previous.temperature ?? null,
    humidity: previous.humidity ?? null,
    light: previous.light ?? null,
    raw: previous.raw || {},
    timestamps: previous.timestamps || {},
    updatedAt: previous.updatedAt || null,
    source: previous.source || null
};

function scalar(value) {
    if (value && typeof value === "object") {
        if (value.value !== undefined) return value.value;
        if (value.state !== undefined) return value.state;
        if (value.payload !== undefined) return value.payload;
    }
    return value;
}

function booleanValue(value) {
    const raw = scalar(value);
    if (typeof raw === "boolean") return raw;
    if (typeof raw === "number") return raw !== 0;
    const normalized = String(raw ?? "").trim().toLowerCase();
    if (["true", "1", "on", "start", "started", "running", "operation", "active"].includes(normalized)) return true;
    if (["false", "0", "off", "stop", "stopped", "idle", "inactive"].includes(normalized)) return false;
    return null;
}

function numericValue(value, fields) {
    let raw = value;
    if (raw && typeof raw === "object") {
        for (const field of fields) {
            if (raw[field] !== undefined) {
                raw = raw[field];
                break;
            }
        }
        raw = scalar(raw);
    }
    if (typeof raw === "number") return Number.isFinite(raw) ? raw : null;
    const match = String(raw ?? "").replace(",", ".").match(/-?\d+(?:\.\d+)?/);
    if (!match) return null;
    const parsed = Number(match[0]);
    return Number.isFinite(parsed) ? parsed : null;
}

function rawValue(value) {
    if (typeof value === "string") return value;
    try {
        return JSON.stringify(value);
    } catch (error) {
        return String(value);
    }
}

const topic = String(msg.topic || "");
if (topic !== "dashboard/init") {
    const active = booleanValue(msg.payload);
    const now = Date.now();
    let key = null;

    switch (topic) {
        case "room/StartRobot":
            key = "startRobot";
            state.startRobot = active;
            if (active === true) {
                state.robot = true;
                state.stopRobot = false;
            }
            break;
        case "room/StopRobot":
            key = "stopRobot";
            state.stopRobot = active;
            if (active === true) {
                state.robot = false;
                state.startRobot = false;
            }
            break;
        case "room/StartButton":
            key = "startButton";
            state.startButton = active;
            if (active === true) {
                state.conveyor = true;
                state.stopButton = false;
            }
            break;
        case "room/StopButton":
            key = "stopButton";
            state.stopButton = active;
            if (active === true) {
                state.conveyor = false;
                state.startButton = false;
            }
            break;
        case "room/temperature":
            key = "temperature";
            state.temperature = numericValue(msg.payload, ["temperature", "Temperature"]);
            break;
        case "room/humidity":
            key = "humidity";
            state.humidity = numericValue(msg.payload, ["humidity", "Humidity"]);
            break;
        case "room/LightIntensity":
            key = "light";
            state.light = numericValue(msg.payload, ["light", "LightIntensity", "lightIntensity"]);
            break;
    }

    if (key) {
        state.raw[key] = rawValue(msg.payload);
        state.timestamps[key] = now;
        state.updatedAt = now;
        state.source = topic;
        flow.set("actuatorsAndSensorsState", state);
    }
}

msg.topic = "actuators-and-sensors/state";
msg.payload = state;
return msg;

const previous = flow.get("smartFactoryDashboardState") || {};
const state = {
    temperature: previous.temperature ?? null,
    humidity: previous.humidity ?? null,
    light: previous.light ?? null,
    robot: previous.robot ?? null,
    conveyor: previous.conveyor ?? null,
    robotEvent: previous.robotEvent || "Waiting for status",
    conveyorEvent: previous.conveyorEvent || "Waiting for status",
    updatedAt: previous.updatedAt || null,
    source: previous.source || null
};

function scalar(value) {
    if (value && typeof value === "object") {
        if (value.value !== undefined) return value.value;
        if (value.state !== undefined) return value.state;
        if (value.payload !== undefined) return value.payload;
    }
    return value;
}

function numberValue(value) {
    const parsed = Number.parseFloat(scalar(value));
    return Number.isFinite(parsed) ? parsed : null;
}

function booleanValue(value) {
    const raw = scalar(value);
    if (typeof raw === "boolean") return raw;
    if (typeof raw === "number") return raw !== 0;
    const normalized = String(raw ?? "").trim().toLowerCase();
    if (["true", "1", "on", "start", "started", "running", "operation", "active"].includes(normalized)) return true;
    if (["false", "0", "off", "stop", "stopped", "idle", "inactive"].includes(normalized)) return false;
    return null;
}

const topic = String(msg.topic || "");
const value = msg.payload;
const bool = booleanValue(value);

switch (topic) {
    case "room/temperature": {
        const reading = numberValue(value);
        if (reading !== null) state.temperature = reading;
        break;
    }
    case "room/humidity": {
        const reading = numberValue(value);
        if (reading !== null) state.humidity = reading;
        break;
    }
    case "room/LightIntensity": {
        const reading = numberValue(value);
        if (reading !== null) state.light = reading;
        break;
    }
    case "room/StartRobot":
        if (bool === true) {
            state.robot = true;
            state.robotEvent = "Start Robot active";
        }
        break;
    case "room/StopRobot":
        if (bool === true) {
            state.robot = false;
            state.robotEvent = "Stop Robot active";
        }
        break;
    case "room/StartButton":
        if (bool === true) {
            state.conveyor = true;
            state.conveyorEvent = "Start Button active";
        }
        break;
    case "room/StopButton":
        if (bool === true) {
            state.conveyor = false;
            state.conveyorEvent = "Stop Button active";
        }
        break;
}

state.updatedAt = Date.now();
state.source = topic;
flow.set("smartFactoryDashboardState", state);
msg.topic = "smart-factory/state";
msg.payload = state;
return msg;
